css:
.dcx,.dcx{margin:0;padding:0;background:#FFFFFF;font-family:'Plus Jakarta Sans',system-ui,sans-serif;color:#111A16;-webkit-font-smoothing:antialiased}
.dcx a{color:#0F7A3D;text-decoration:none}
.dcx header a{white-space:nowrap;flex-shrink:0}
.dcx a:hover{color:#0A5C2D}
.dcx .nx-btn{white-space:nowrap;flex-shrink:0;transition:transform .16s ease-out,box-shadow .16s ease-out}
.dcx .nx-btn:hover{transform:translateY(-1px);box-shadow:0 10px 22px -12px rgba(15,122,61,.6)}
.dcx .nx-card{transition:transform .18s ease-out,box-shadow .18s ease-out}
.dcx .nx-card:hover{transform:translateY(-2px);box-shadow:0 16px 32px -22px rgba(17,26,22,.4)}
.dcx .nx-row{transition:background .15s}
.dcx .nx-row:hover{background:#F6FAF7}
@keyframes nxUp{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}
.dcx [data-anim]{animation:nxUp .62s cubic-bezier(.22,.8,.3,1) both}
@keyframes nxDash{to{stroke-dashoffset:-40}}
.dcx .nx-dash{stroke-dasharray:4 5;animation:nxDash 1.6s linear infinite}
@media (max-width:1100px){.dcx [data-nx-nav]{display:none!important}
}
@media (max-width:1040px){.dcx [data-nx="split"],.dcx [data-nx="multi"],.dcx [data-nx="two"]{grid-template-columns:minmax(0,1fr)!important}
.dcx [data-nx="rail"],.dcx [data-nx="col"],.dcx [data-nx="wires"]{display:none!important}
.dcx [data-nx="app"],.dcx [data-nx="mock"]{grid-template-columns:minmax(0,1fr)!important}
.dcx [data-nx="g4"]{grid-template-columns:repeat(2,minmax(0,1fr))!important}
}
@media (max-width:760px){.dcx [data-nx="g4"],.dcx [data-nx="kpi"],.dcx [data-nx="rules"]{grid-template-columns:minmax(0,1fr)!important}
.dcx section > div{padding-left:18px!important;padding-right:18px!important}
}

